  pie = drLineaCliente(visual && visual.caption, 1500);
  texto = pie;
  textoReporte = tipo === 'image' ? '(imagen) la persona envió una foto' : '(documento) la persona envió un archivo';
  categoria = mediaId !== '' ? 'medio' : 'otro';
