  if (pregunta && CM_PREGUNTA_DE_BOT.test(pregunta) && /\b(no|nop|nel|para nada)\b/.test(n) && !/\b(asistente|virtual)\b/.test(n)) return 'identidad';
  for (const re of (o.prohibidos || [])) if (re.test(n)) return 'prohibido';
