      const n = cmNormEnlace(e);
      // Nunca `http://` (un enlace del negocio es https), nunca `..` ni `@` en la ruta, ni otro enlace dentro de él (`?next=https://…`).
      if (/^http:\/\//i.test(e) || /^[a-z][a-z0-9+.-]*:\/\//i.test(e) && !/^https:\/\//i.test(e)) return 'enlace_ajeno';
